using System.ComponentModel.DataAnnotations;

namespace Visma.Core.Entities;

/// <summary>
/// A staff member who can receive visitors ("the person being visited").
/// Hosts are kept in a managed directory so receptionists pick from a list instead of
/// typing free text. Hosts are never hard-deleted once they have visits; they are
/// deactivated (<see cref="IsActive"/> = false) so visit history stays intact.
/// </summary>
public class Host
{
    /// <summary>Primary key (auto-generated by the database).</summary>
    public int Id { get; set; }

    /// <summary>Host's full name, e.g. "Dr. Chinedu Eze".</summary>
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, MinimumLength = 2, ErrorMessage = "Full name must be between 2 and 100 characters.")]
    [Display(Name = "Full name")]
    public string FullName { get; set; } = string.Empty;

    /// <summary>Department or office the host belongs to, e.g. "Admissions".</summary>
    [Required(ErrorMessage = "Department is required.")]
    [StringLength(100)]
    public string Department { get; set; } = string.Empty;

    /// <summary>Optional work e-mail.</summary>
    [EmailAddress(ErrorMessage = "Enter a valid e-mail address.")]
    [StringLength(100)]
    [Display(Name = "E-mail")]
    public string? Email { get; set; }

    /// <summary>Optional phone / extension.</summary>
    [Phone(ErrorMessage = "Enter a valid phone number.")]
    [StringLength(20)]
    [Display(Name = "Phone / extension")]
    public string? Phone { get; set; }

    /// <summary>Only active hosts can receive new visits.</summary>
    [Display(Name = "Active")]
    public bool IsActive { get; set; } = true;

    /// <summary>All visits made to this host (navigation property, 1-to-many).</summary>
    public ICollection<Visit> Visits { get; set; } = new List<Visit>();
}
